(() => {
  const pres = Array.from(document.querySelectorAll('pre'));
  const sig = pres.find(p => p.innerText.includes('roundRect('));
  const sigText = sig ? sig.innerText : 'not found';
  const html = sig ? sig.outerHTML.slice(0, 3000) : '';
  return {sigText, preCount: pres.length, html};
})()

