  const codes = Array.from(document.querySelectorAll('code'));
  const hits = codes.filter(c => c.innerText.includes('roundRect('));
  return hits.map(h => h.innerText).join('\n===\n') + '\nTOTAL: ' + hits.length;
})()

(() => {
  // find all elements whose text contains "roundRect(x, y" pattern
  const all = document.querySelectorAll('*');
  const found = [];
  for (const el of all) {
    if (el.children.length === 0 || el.tagName === 'CODE' || el.tagName === 'PRE' || el.tagName === 'LI' || el.tagName === 'DT') {
      const t = el.innerText || '';
      if (/roundRect\(/.test(t) && t.length < 400) {
        found.push(el.tagName + ': ' + t.replace(/\s+/g, ' '));
      }
    }
  }
  return found.slice(0, 20).join('\n---\n');
})()

(() => {
  const canvas = document.createElement('canvas');
  canvas.width = 200; canvas.height = 200;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#00ff00';
  ctx.beginPath();
  ctx.roundRect(50, 50, 100, 100, [10, 20, 30, 40]);
  ctx.fill();
  const { data, width, height } = ctx.getImageData(0, 0, 200, 200);
  let filled = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i+3] > 0) filled++;
  }
  // Also sample specific corners to show rounding differences:
  const px = (x, y) => { const i = (y*width+x)*4; return [data[i], data[i+1], data[i+2], data[i+3]]; };
  return {
    canvasSize: [canvas.width, canvas.height],
    totalPixels: width*height,
    filledPixelCount: filled,
    // Check corner pixels — TL has r=10 so (52,52) should be filled but (50,50) won't
    TL_center_50_50: px(50, 50),   // outside r=10 arc
    TL_inside_51_51: px(51, 51),   // just inside r=10 arc?
    TL_deep_60_60:  px(60, 60),    // definitely inside
    TR_center_149_50: px(149, 50), // r=20 top-right
    BR_149_149: px(149, 149),      // r=30 bottom-right
    BL_50_149: px(50, 149),        // r=40 bottom-left
    dead_center_100_100: px(100, 100)
  };
})()
